from collections import Counter
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    # 1) horizontal gap fill in bar rows (rows with >=2 distinct nonzero colors)
    for i,row in enumerate(g):
        nz=[(j,c) for j,c in enumerate(row) if c]
        if len(set(c for _,c in nz))<2: continue
        cnt=Counter(c for _,c in nz); bc=max(cnt.items(), key=lambda kv:kv[1])[0]
        js=sorted(j for j,c in nz if c==bc)
        prev=None
        for j in js:
            if prev is None: prev=j; continue
            if j>prev+1:
                for x in range(prev+1,j):
                    if row[x]==0: row[x]=bc
                    for r in range(i):
                        if g[r][x]==0: g[r][x]=bc
            prev=j
    # 2) strays: cells in rows that have exactly one distinct nonzero color and are single isolated below a bar
    for i,row in enumerate(g):
        nz=[(j,c) for j,c in enumerate(row) if c]
        cols=set(c for _,c in nz)
        if len(cols)!=1 or len(nz)!=1: continue
        c=nz[0][1]; j=nz[0][0]
        # extend up while background, down while background (both directions independently per cell)
        for sgn in (1,-1):
            r=i+sgn
            while 0<=r<h and g[r][j]==0: g[r][j]=c; r+=sgn
    return g
