    for i,row in enumerate(g):
        for v,e,beg in lines_of_row(row):
            for x in range(beg+1,e):
                if row[x]==0: row[x]=v
    # 2) upward extension from every gap column of every bar-row run, bottom-to-top order
    order=sorted(range(h),reverse=True)
