            # extend from each cell of the run that had a zero neighbor inside span? use all columns beg..e
            for x in range(beg,e+1):
                rr=i-1
                while rr>=0 and g[rr][x]==0:
                    g[rr][x]=v; rr-=1
    # 3) strays: cells not part of any run with width>=2? treat isolated single-cell runs in non-bar rows
    barset=set(i for i in range(h) if any(e>beg for _,e,beg in lines_of_row(g[i])))
    for i in range(h):
        if i in barset: continue
        for v,e,beg in lines_of_row(g[i]):
            if e==beg:
