def solve(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    # 1) horizontal gap fill: for each row, each interior zero-run strictly between two runs
    for i in range(h):
        row=g[i]; segs=[]; j=0
        while j<w:
            if row[j]==0: j+=1; continue
            v=row[j]; s=j
            while j<w and row[j]==v: j+=1
            segs.append((v,s,j-1))
        for k in range(1,len(segs)):
            a,b=segs[k-1],segs[k]
            if b[1]-a[2]>1:
                col=a[0] if (b[1]-b[0]+1)>= (a[2]-a[1]+1) else b[0]
                for x in range(a[2]+1,b[1]): g[i][x]=col
    # 2) vertical channels: columns with a vertical run >=2, extend both dirs through bg,
    #    recoloring at each horizontal bar crossing (nonzero run in that column).
    ch_cols=set()
    for c in range(w):
        col=[g[r][c] for r in range(h)]
        r=0
        while r<h:
            if col[r]!=0:
                s=r
                while r<h and col[r]==col[s]: r+=1
                if r-s>=2: ch_cols.add(c)
            else: r+=1
    for c in ch_cols:
        col=[g[r][c] for r in range(h)]
        # marker: original bar cells in this column (non-bg, not part of horizontal-gap fills? use nonzero count>=2 in original? use final grid runs)
        r=0
        while r<h:
            if col[r]!=0:
                s=r
                while r<h and col[r]==col[s]: r+=1
                lo,hi=s-1,r-1
                # extend up through bg, recolor at crossings
                rr=lo-1
                while rr>=0 and g[rr][c]==0:
                    g[rr][c]=col[s]
                    rr-=1
                rr=hi+1
                while rr<h and g[rr][c]==0:
                    g[rr][c]=col[s]
                    rr+=1
            else: r+=1
    return g

